{
  "spec": "This change extends the todo app to support optional due dates (YYYY-MM-DD) and task completion status. Tasks are stored in JSON with new fields `due_date` and `done`. The CLI gains `--due` flag for adding tasks, a `done` command to mark completion, and an `overdue` command to list incomplete tasks past their due date. The list view updates to display due dates when present, maintaining backward compatibility with existing JSON files lacking these fields.",
  "stack": "Python, standard library (json, argparse, datetime), pytest",
  "tasks": [
    {
      "id": 1,
      "title": "Update Task model to support due_date and done fields",
      "files": [
        "todo/model.py"
      ],
      "test": "tests/test_todo.py: test_model_fields checks that Task constructor accepts and stores due_date and done attributes correctly."
    },
    {
      "id": 2,
      "title": "Update storage to handle optional due_date and done in JSON",
      "files": [
        "todo/storage.py"
      ],
      "test": "tests/test_todo.py: test_storage_roundtrip checks that tasks with due_date and done are saved and loaded correctly, and old files without these fields load as defaults."
    },
    {
      "id": 3,
      "title": "Add --due argument to add command and update CLI parsing",
      "files": [
        "todo/cli.py"
      ],
      "test": "tests/test_todo.py: test_add_with_due checks that adding a task with --due sets the due_date in the stored task."
    },
    {
      "id": 4,
      "title": "Implement done command to mark task as completed",
      "files": [
        "todo/cli.py"
      ],
      "test": "tests/test_todo.py: test_done_command checks that running done ID marks the task as done in storage."
    },
    {
      "id": 5,
      "title": "Implement overdue command to list incomplete past-due tasks",
      "files": [
        "todo/cli.py",
        "todo/listing.py"
      ],
      "test": "tests/test_todo.py: test_overdue_command checks that overdue lists only incomplete tasks with due_date before today, sorted oldest first."
    },
    {
      "id": 6,
      "title": "Update list rendering to show due date when present",
      "files": [
        "todo/listing.py"
      ],
      "test": "tests/test_todo.py: test_list_with_due checks that list output includes the due date after the task text when present."
    }
  ]
}

